//! `cargo xtask bindgen`: generates the libretro bindings of
//! `neptron-libretro-sys` from the vendored `libretro.h`.
//!
//! The command runs the `bindgen` command-line tool, so no build needs
//! libclang. The generated files are committed. The command always generates
//! for `x86_64-unknown-linux-gnu` with `-ffreestanding`, so the output does not
//! depend on the host or its system headers: only clang's own headers are read.

use std::path::{Path, PathBuf};
use std::process::Command;

use crate::repo::{self, Repo, RepoError};

/// An error of the bindings generator.
#[derive(Debug, thiserror::Error)]
pub enum BindgenError {
    /// The arguments are wrong.
    #[error("usage: cargo xtask bindgen")]
    Usage,
    /// The repository cannot be found, or a tool fails.
    #[error(transparent)]
    Repo(#[from] RepoError),
}

/// Runs `cargo xtask bindgen`: writes `src/bindings.rs` and
/// `src/core_api_decls.rs` of `neptron-libretro-sys`, then formats them.
pub fn run(args: &[&str]) -> Result<(), BindgenError> {
    if !args.is_empty() {
        return Err(BindgenError::Usage);
    }
    let repo = Repo::discover()?;
    let crate_dir = repo.root.join(CRATE_DIR);
    let header = crate_dir.join(HEADER);
    let tool = std::env::var_os(TOOL_ENV).map_or_else(|| PathBuf::from("bindgen"), PathBuf::from);
    for output in OUTPUTS {
        let path = crate_dir.join(output.file);
        let mut cmd = Command::new(&tool);
        cmd.args(bindgen_args(&header, &path, output.selection));
        repo::output(cmd.current_dir(&repo.root))?;
        let mut fmt = Command::new("rustfmt");
        fmt.args(["--edition", "2024"]).arg(&path);
        repo::output(fmt.current_dir(&repo.root))?;
        println!("wrote {}", path.display());
    }
    Ok(())
}

/// Environment variable that names the `bindgen` executable. The default is
/// `bindgen` on the `PATH`.
pub const TOOL_ENV: &str = "NEPTRON_BINDGEN";

/// Which part of the header one output file holds.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Selection {
    /// Every `retro_*` type and every `RETRO_*` constant, no functions.
    Types,
    /// The core entry points (`retro_init`, `retro_run`, ...) and no types.
    /// The file imports the types from the crate root.
    CoreApi,
}

/// One generated file.
#[derive(Debug, Clone, Copy)]
pub struct Output {
    /// File name in the `src` directory of the crate.
    pub file: &'static str,
    /// What the file holds.
    pub selection: Selection,
}

/// The generated files.
pub const OUTPUTS: [Output; 2] = [
    Output {
        file: "src/bindings.rs",
        selection: Selection::Types,
    },
    Output {
        file: "src/core_api_decls.rs",
        selection: Selection::CoreApi,
    },
];

/// The arguments of one `bindgen` run.
pub fn bindgen_args(header: &Path, output: &Path, selection: Selection) -> Vec<String> {
    let mut args = vec![
        header.display().to_string(),
        "--output".to_owned(),
        output.display().to_string(),
        "--rust-target".to_owned(),
        RUST_TARGET.to_owned(),
        "--rust-edition".to_owned(),
        "2024".to_owned(),
        // The header documents in Doxygen. As rustdoc text its indented
        // blocks become doctests that do not compile.
        "--no-doc-comments".to_owned(),
        "--no-prepend-enum-name".to_owned(),
        "--merge-extern-blocks".to_owned(),
        "--formatter".to_owned(),
        "none".to_owned(),
        "--raw-line".to_owned(),
        GENERATED_NOTE.to_owned(),
    ];
    let selection_args: &[&str] = match selection {
        Selection::Types => &[
            "--allowlist-type",
            "retro_.*",
            "--allowlist-var",
            "RETRO_.*",
            "--blocklist-function",
            ".*",
        ],
        Selection::CoreApi => &[
            "--allowlist-function",
            "retro_.*",
            "--blocklist-type",
            ".*",
            "--raw-line",
            "use crate::*;",
        ],
    };
    args.extend(selection_args.iter().map(|s| (*s).to_owned()));
    args.extend(CLANG_ARGS.iter().map(|s| (*s).to_owned()));
    args
}

const CRATE_DIR: &str = "crates/neptron-libretro-sys";
const HEADER: &str = "vendor/libretro.h";
const RUST_TARGET: &str = "1.85";
const GENERATED_NOTE: &str =
    "// Generated by `cargo xtask bindgen` from vendor/libretro.h. Do not edit.";
const CLANG_ARGS: [&str; 3] = ["--", "--target=x86_64-unknown-linux-gnu", "-ffreestanding"];

#[cfg(test)]
mod tests {
    use super::*;

    fn args(selection: Selection) -> Vec<String> {
        bindgen_args(Path::new("h/libretro.h"), Path::new("out.rs"), selection)
    }

    fn has_pair(args: &[String], key: &str, value: &str) -> bool {
        args.windows(2).any(|w| w[0] == key && w[1] == value)
    }

    #[test]
    fn header_and_output_come_first() {
        let a = args(Selection::Types);
        assert_eq!(a[0], "h/libretro.h");
        assert!(has_pair(&a, "--output", "out.rs"));
    }

    #[test]
    fn clang_target_is_fixed_and_freestanding() {
        for selection in [Selection::Types, Selection::CoreApi] {
            let a = args(selection);
            let tail = &a[a.len() - CLANG_ARGS.len()..];
            assert_eq!(tail, CLANG_ARGS);
        }
    }

    #[test]
    fn types_file_has_no_functions() {
        let a = args(Selection::Types);
        assert!(has_pair(&a, "--blocklist-function", ".*"));
        assert!(has_pair(&a, "--allowlist-type", "retro_.*"));
        assert!(has_pair(&a, "--allowlist-var", "RETRO_.*"));
    }

    #[test]
    fn core_api_file_has_no_types_and_imports_them() {
        let a = args(Selection::CoreApi);
        assert!(has_pair(&a, "--blocklist-type", ".*"));
        assert!(has_pair(&a, "--allowlist-function", "retro_.*"));
        assert!(has_pair(&a, "--raw-line", "use crate::*;"));
    }

    #[test]
    fn outputs_are_in_the_crate_source() {
        for output in OUTPUTS {
            assert!(output.file.starts_with("src/"), "{}", output.file);
        }
    }
}
